import ssda

ssda.define_cond('live_group', {
    '생계급여 수급자': 'nbls_live_yn1 == 1'
}, other='생계급여 비수급자')

r = ssda.mean('p_disp_bn_amt', where='disp_bn_yn1 == 1', by='live_group')
print(r)

import ssda

ssda.define_cond('disability_group', {
    '등록장애인': 'dis_yn == 1'
}, other='비장애인')

result = ssda.poverty_rate(where='age >= 65', by='disability_group')
print(result)

